# Problema 5 - Calculadora de Costo de Envio
# El usuario ingresa peso y distancia de varios paquetes
# Se calcula el costo de envio segun reglas y se acumula el total
total_acumulado = 0
while True:
    # INPUT
    entrada_peso = input("Ingresa el peso en kg (o 'exit' para terminar): ")
    if entrada_peso.lower() == "exit":
        break
    peso = float(entrada_peso)
    distancia = float(input("Ingresa la distancia en km: "))
    # PROCESS
    if distancia <= 100:
        if peso <= 5:
            costo = 50.00
        else:
            costo = 80.00
    else:
        if peso <= 5:
            costo = 120.00
        else:
            costo = 200.00

    total_acumulado += costo
    # OUTPUT
    print(f"Shipping cost: ${costo:.2f} MXN")
print(f"Total: ${total_acumulado:.2f} MXN")

# Problema 4 - Clasificador de Estaciones
# El usuario ingresa numeros de mes uno por uno
# Se muestra la estacion correspondiente hasta que escriba "exit"
while True:
    # INPUT
    entrada = input("Ingresa el numero de mes (o 'exit' para terminar): ")
    if entrada.lower() == "exit":
        break
    mes = int(entrada)
    # PROCESS
    if mes < 1 or mes > 12:
        resultado = "Invalid month. Please enter a number between 1 and 12."
    elif mes in (12, 1, 2):
        resultado = "Winter"
    elif mes in (3, 4, 5):
        resultado = "Spring"
    elif mes in (6, 7, 8):
        resultado = "Summer"
    else:
        resultado = "Fall"
    # OUTPUT
    print(resultado)

